ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "tarot-meanings"


MAJOR = [
    ("The Fool", "The. fool.png", "0", "Beginnings · trust · possibility", "The Fool opens a new chapter with curiosity and room to experiment. It can describe a leap into unfamiliar territory, the freedom of not having every answer, or the willingness to meet life before a plan is perfect. Its invitation is not to ignore risk, but to pair openness with enough care to stay present to the consequences.", "Reversed, the Fool can point to hesitation that keeps a genuine beginning out of reach, or to a leap taken without noticing the ground ahead. Fear of looking inexperienced may be holding you back; alternatively, excitement may be outrunning preparation. Ask whether this pause is wise caution or avoidance, and whether one small, reversible first step could offer clarity.", "What beginning is drawing your curiosity, and what would help you approach it with both courage and care?"),
    ("The Magician", "Magican.png", "I", "Resourcefulness · focus · initiative", "The Magician is about turning intention into action. The tools are already on the table: skills, knowledge, time, relationships, and the ability to communicate what you want. This card asks you to bring those resources together around one clear aim. Potential becomes useful when attention is focused and an idea is given a real first form.", "Reversed, the Magician can describe scattered attention, underestimating your own abilities, or having resources you have not yet put to honest use. It can also ask for care around persuasion: are words being used to clarify and create, or to impress, evade, or control? Reclaim focus, check the facts, and choose a transparent next action.", "Which abilities or resources do you already have that could make one intention concrete?"),
    ("The High Priestess", "High priestess.png", "II", "Intuition · quiet · the unseen", "The High Priestess invites attentive stillness. Some information is not ready to be resolved by more effort; subtle feelings, incomplete facts, and what has gone unsaid may need room to surface. This is a card of listening rather than assuming that a hunch is proof. Give inner impressions respect while remaining curious about what you do not yet know.", "Reversed, the High Priestess may suggest that inner signals are being drowned out, or that uncertainty is being filled with projection. A private matter may need clearer words, or a pause may have become avoidance. Separate what you observed from what you inferred; seek trustworthy information and let intuition inform your judgment without replacing it.", "What do you sense beneath the first explanation, and what evidence would help you understand it more clearly?"),
    ("The Empress", "The Emperess.png", "III", "Nurturing · creativity · abundance", "The Empress speaks to growth supported by care. A relationship, creative project, body, or home may be asking for patience and nourishing attention rather than force. Abundance here is not simply having more; it is noticing what is alive, tending it well, and allowing pleasure, connection, and creativity to be part of a sustainable life.", "Reversed, the Empress can point to creative depletion, neglect of your own needs, or care that has become overgiving. Growth may be blocked by comparison or by trying to control its pace. Ask where nourishment is missing, whether support is being exchanged fairly, and what small act of care would restore a healthier relationship with your energy.", "What in your life is growing, and what kind of care would help it grow without draining you?"),
    ("The Emperor", "The Emperor.png", "IV", "Structure · boundaries · steadiness", "The Emperor brings attention to structure, responsibility, and the boundaries that make sustained effort possible. A clear plan can protect what matters and make a difficult situation more manageable. Authority is most useful when it creates stability without silencing others; aim for consistent leadership, practical limits, and rules that still leave room to respond to reality.", "Reversed, the Emperor may show rigidity, overcontrol, or a structure that no longer serves the people inside it. In another context, missing boundaries or inconsistent leadership may be creating instability. Notice whether you are gripping too tightly or avoiding responsibility, then define one fair limit or practical agreement that can be followed.", "Where would a clearer boundary or a more flexible plan create genuine stability?"),
    ("The Hierophant", "62.png", "V", "Learning · tradition · shared values", "The Hierophant concerns learning within a tradition, community, or trusted system of knowledge. Guidance from a teacher or shared practice can offer structure and belonging, especially when you are new to a subject. The card also asks you to examine the values underneath the rules: inherit what helps you live with integrity, and understand what you are choosing.", "Reversed, the Hierophant may reflect pressure to conform, beliefs accepted without examination, or the need to find a path outside an established framework. It can also warn against rejecting useful guidance merely to prove independence. Compare advice with your values and lived experience; choose your teachers and communities with care.", "Which beliefs or traditions genuinely support the person you want to become?"),
    ("The Lovers", "Lovers.png", "VI", "Connection · values · choice", "The Lovers represents meaningful connection and the choices that shape it. Attraction may be present, but the deeper question is whether honesty, respect, and shared values can support the bond. This card can also appear when two possibilities ask you to choose with integrity. A good decision is not always effortless; it is one you can stand behind.", "Reversed, the Lovers may show distance, unresolved tension, unequal commitment, or a choice made against your own values. It does not automatically mean a relationship must end. Name what is not being said, listen for differences beneath the surface, and consider whether both people can take part in repair without abandoning themselves.", "Which choice or connection allows you to act in a way that feels honest and mutual?"),
    ("The Chariot", "Chariot.png", "VII", "Direction · discipline · momentum", "The Chariot is purposeful movement through competing pressures. Progress depends on choosing a direction and guiding different needs rather than pretending they do not conflict. Confidence and discipline can carry you forward, but the card also asks you to remain responsive; momentum is valuable when you are steering it, not simply pushing harder.", "Reversed, the Chariot may signal scattered effort, a lost sense of direction, or momentum driven by urgency rather than intention. Trying to control every variable can be as unhelpful as giving up on the route. Stop long enough to decide what matters most, then set a pace you can sustain and review along the way.", "What direction deserves your effort, and what competing pull needs to be acknowledged first?"),
    ("Strength", "65.png", "VIII", "Courage · patience · compassion", "Strength describes courage expressed through patience and compassion. It is the steadiness to stay with a difficult feeling without letting it dictate every action. Influence may come through calm boundaries, self-respect, and gentle persistence rather than force. This card honours the ongoing work of relating wisely to instinct, fear, and vulnerability.", "Reversed, Strength can reflect self-doubt, depleted patience, or reacting more harshly than you intend. Sometimes the challenge is not to become tougher but to stop measuring yourself by constant endurance. Notice where you need rest, encouragement, or a boundary, and treat vulnerability as information rather than a failure.", "What would a courageous response look like if it included compassion for yourself?"),
    ("The Hermit", "Hermit.png", "IX", "Reflection · solitude · perspective", "The Hermit marks a useful retreat for reflection. Time alone, careful study, or distance from outside noise can help you hear your own judgment again. Solitude is most nourishing when it leads to understanding that can re-enter daily life. You do not need to solve everything immediately; a quieter pace may show which question is truly yours.", "Reversed, the Hermit can point to isolation that has lasted too long, or to avoiding a necessary inner question by staying constantly occupied. It may also indicate that advice is being sought from others while your own experience goes unheard. Reconnect at a pace that feels safe and consider who can offer thoughtful company.", "What becomes easier to hear when you step away from the noise, and who could help you reconnect?"),
    ("Wheel of Fortune", "Wheel of Fortune.png", "X", "Cycles · turning points · adaptation", "The Wheel of Fortune reflects changing conditions and the cycles that shape a situation. A shift may open an opportunity or close a familiar chapter, often without being fully under your control. This card is not a guarantee of luck; it asks you to notice timing, adapt intelligently, and distinguish the changing circumstances from the choices that remain yours.", "Reversed, the Wheel may describe resistance to a change already underway, repeating a pattern without examining it, or feeling caught in a difficult cycle. It can also remind you that a temporary setback is not the whole story. Identify what is within your influence, what must be accepted for now, and what pattern you can interrupt.", "What is changing around you, and what part of your response remains within your control?"),
    ("Justice", "Justice.png", "XI", "Fairness · truth · accountability", "Justice asks for clear-eyed honesty, fair process, and accountability. The facts matter, as do the effects of your decisions on everyone involved. This card can invite a review of agreements, responsibilities, or consequences. Aim to be balanced rather than simply vindicated: a fair outcome often begins with the willingness to see your own part clearly.", "Reversed, Justice may highlight an unfair arrangement, incomplete information, or the temptation to avoid responsibility. It can also warn against judging yourself or someone else before the facts are understood. Recheck assumptions, make space for the perspectives being missed, and decide what repair or clearer agreement would be proportionate.", "What would a fair reading of the facts include, even if it is uncomfortable?"),
    ("The Hanged Man", "Hanged man.png", "XII", "Pause · surrender · new perspective", "The Hanged Man suggests a pause that can change how a problem is seen. Progress may come from loosening your grip, accepting a temporary uncertainty, or giving up an approach that is no longer working. This is not passive resignation: it is a deliberate willingness to look from another angle before deciding what action is worthwhile.", "Reversed, the Hanged Man can signal being stuck in a pause that has lost its purpose, resisting a perspective shift, or sacrificing more than the situation requires. Ask whether waiting is producing insight or simply postponing a difficult choice. A small decision or boundary may restore movement without forcing a premature solution.", "What might look different if you stopped trying to force the current approach?"),
    ("Death", "70.png", "XIII", "Ending · release · transformation", "Death represents an ending or transformation, not a literal prediction of death. A role, habit, expectation, or chapter may have reached its natural limit. Acknowledging what is finished can make room for a different beginning, though grief and relief may coexist. Change becomes more workable when you stop demanding that the old form continue unchanged.", "Reversed, Death may reflect clinging to a phase that has ended, postponing a necessary transition, or fearing the uncertainty that follows release. Sometimes the change is already happening internally even if it is not visible yet. Identify what you are trying to preserve, what it costs, and what support could make a gradual transition possible.", "What may be complete, and what would you need in order to let the next chapter take shape?"),
    ("Temperance", "Temperance.png", "XIV", "Balance · integration · patience", "Temperance is the art of bringing different needs into workable relationship. Progress may come through a measured adjustment, collaboration, or a rhythm that is more sustainable than an all-or-nothing response. The card values patience and experimentation: combine what is useful, notice the effect, and allow time for a steadier balance to develop.", "Reversed, Temperance can point to excess, impatience, or parts of life that are not being given compatible amounts of attention. It may also suggest trying to accommodate everyone until your own limits disappear. Reassess the pace, reduce an avoidable extreme, and make one honest adjustment rather than expecting immediate perfection.", "Which parts of your life need to be brought into better balance, and what is one realistic adjustment?"),
    ("The Devil", "Devil.png", "XV", "Attachment · patterns · agency", "The Devil brings awareness to attachments and patterns that can make freedom feel smaller: a habit, fear, power imbalance, or belief that seems impossible to question. It is not a verdict that you are bad or powerless. Begin by naming the pattern honestly and noticing what it offers, what it costs, and where a choice still exists.", "Reversed, the Devil may describe recognizing a restrictive pattern and beginning to loosen its hold, or struggling to admit how much influence it has. Freedom is often gradual rather than dramatic. Seek practical support where needed, reduce shame, and focus on a concrete choice that increases safety and agency.", "What pattern feels difficult to change, and what small choice could give you more room to act?"),
    ("The Tower", "73.png", "XVI", "Disruption · revelation · rebuilding", "The Tower depicts disruption that exposes a structure that could not safely remain as it was. A sudden truth or change may feel destabilizing, but it can also clarify what was already strained. Focus first on immediate needs and reliable support; once the shock settles, rebuild around what is honest, strong, and genuinely yours.", "Reversed, the Tower may show bracing for a change, delaying an overdue conversation, or trying to preserve stability by avoiding a truth. It can also describe an inner upheaval happening privately. Do not manufacture crisis, but do look carefully at the weak point and prepare a safer, more honest way to address it.", "What has been shaken, and what remains dependable as you decide what to rebuild?"),
    ("The Star", "The Star.png", "XVII", "Hope · renewal · openness", "The Star offers a quieter kind of hope: recovery, renewed perspective, and the willingness to imagine a future after strain. It does not promise that everything will be effortless. It suggests that restoration can begin with small honest acts—rest, connection, creative work, or asking for help—and grow as trust returns.", "Reversed, the Star may reflect discouragement, exhaustion, or difficulty believing that care will make a difference. Hope may feel distant rather than absent. Reduce the scale of the task: seek one source of support, notice one sign of progress, and allow healing to be uneven without treating a difficult day as proof that nothing is changing.", "What small, believable source of renewal could you let into your life now?"),
    ("The Moon", "The Moon.png", "XVIII", "Uncertainty · imagination · feeling", "The Moon describes a passage through uncertainty, where feelings and imagination can be vivid while the facts are incomplete. It asks for attention without rushing to a conclusion. Dreams, fears, and intuitions may reveal what needs care, but they are not automatically evidence. Move gently, verify what can be verified, and give unclear matters time to emerge.", "Reversed, the Moon can mark fears beginning to loosen, confusion coming into view, or anxiety becoming difficult to distinguish from evidence. A hidden concern may be ready for careful attention. Ground yourself in what is known, talk with someone trustworthy, and avoid treating the most frightening interpretation as the only possible one.", "What do you know for certain, what are you imagining, and what might help you feel grounded?"),
    ("The Sun", "Sun.png", "XIX", "Clarity · vitality · joy", "The Sun brings warmth, visibility, and the pleasure of being able to understand where you stand. Confidence may return through honest connection, creative play, or recognising progress that was easy to overlook. Enjoyment is not frivolous here; it can restore energy and help you share success openly without diminishing anyone else's light.", "Reversed, the Sun may describe muted joy, confidence that needs grounding, or a good development obscured by fatigue or unrealistic expectations. It does not erase the positive; it asks you to notice what is preventing you from feeling it. Let progress be real without requiring it to be perfect or constant.", "What is already going well, and how could you allow yourself to recognise it?"),
    ("Judgement", "Judgement.png", "XX", "Review · awakening · response", "Judgement invites an honest review of the past so that it can inform, rather than dictate, your next choice. A realization or call to change may be becoming difficult to ignore. This card is not about punishment; it is about taking stock, acknowledging what you have learned, and deciding how you want to answer now.", "Reversed, Judgement may reflect harsh self-criticism, fear of being evaluated, or delaying a decision because the past still feels unresolved. Learning from a mistake is different from remaining defined by it. Seek a balanced account of what happened, make amends where appropriate, and choose one next step based on who you are becoming.", "What have you learned from the past that you are ready to act on now?"),
    ("The World", "The World.png", "XXI", "Completion · integration · wholeness", "The World marks a cycle reaching meaningful completion. It can reflect the integration of experience, a goal achieved, or a sense that different parts of your life are beginning to fit together. Pause to acknowledge what the work required. Completion is not an ending to growth; it is a foundation from which a new cycle can begin.", "Reversed, the World may point to unfinished business, a delayed milestone, or difficulty allowing yourself to recognise how far you have come. Something may need a final practical step, or a definition of completion that is more realistic. Identify what is genuinely left to do and what can be accepted as good enough to close.", "What deserves to be acknowledged as complete, and what would help you close the loop?"),
]


SUITS = {
    "Wands": {
        "cards": [
            ("Ace", "Ace of Wands.png", "Spark · initiative · creative energy", "The Ace of Wands is a spark of creative or personal energy: a new idea, attraction, invitation, or desire to begin. Inspiration is promising but still needs a place to land. Give the impulse one practical experiment, and notice whether it grows when you give it attention.", "Reversed, the spark may be delayed, scattered, or difficult to trust. Creative energy can be present without a clear outlet, or excitement may fade when the first obstacle appears. Reduce the pressure to produce something perfect and choose a small test that helps distinguish a temporary impulse from a meaningful interest.", "What idea or desire feels alive enough to deserve one small experiment?"),
            ("Two", "Two of wands.png", "Planning · possibility · looking ahead", "The Two of Wands is the moment after an idea becomes possible and before a direction is chosen. You may be comparing a familiar path with a wider horizon. Planning matters, but it cannot remove every uncertainty. Gather the information you need, then decide which possibility is worth developing.", "Reversed, the Two of Wands may indicate hesitation, a plan that remains abstract, or fear of leaving a known position. It can also suggest choosing too quickly to escape uncertainty. Make the next step specific and modest; a real trial often provides better information than endless comparison.", "Which future are you considering, and what would a low-risk first step teach you?"),
            ("Three", "three of wands.png", "Expansion · progress · wider horizons", "The Three of Wands looks outward as early efforts begin to create room for expansion. Partnerships, new audiences, travel, or longer-range plans may come into view. Progress is underway, though not yet complete. Keep following through and remain open to opportunities arriving from beyond your original plan.", "Reversed, the Three of Wands may reflect delays, constrained plans, or disappointment that growth is taking longer than expected. The horizon may be narrower for now, but that does not make the work meaningless. Revisit timing, communication, and assumptions; adjust the route before abandoning a goal that still matters.", "Where are you waiting for progress, and what part of the plan can you influence today?"),
            ("Four", "four of wands.png", "Celebration · belonging · a stable milestone", "The Four of Wands celebrates a milestone, shared effort, or place where you can feel welcome. Stability may come through community as much as through individual achievement. Marking progress helps people recognise what they built together and gives you a moment to enjoy the foundation before the next task begins.", "Reversed, the Four of Wands may point to a celebration delayed, tension around belonging, or a home or group arrangement that feels less secure than it appears. It may be wise to define what support and stability mean for you personally rather than forcing an ideal occasion. A smaller, more honest acknowledgement can still matter.", "Who helps you feel at home, and what milestone deserves to be recognised?"),
            ("Five", "5 of wands.png", "Friction · competition · testing ideas", "The Five of Wands brings competing ideas, energetic disagreement, or a test of how people work together. Friction can reveal what needs to be clarified, but it can also waste energy when nobody is listening. Separate useful challenge from personal attack and agree on what the discussion is meant to accomplish.", "Reversed, the Five of Wands can indicate conflict being avoided, competition becoming exhausting, or a group beginning to move beyond its disagreements. Quiet does not always mean resolution. Name the tension without escalating it, and decide whether a fair conversation or a clear boundary is more useful now.", "Which disagreement is helping ideas improve, and which one is only consuming energy?"),
            ("Six", "6 of wands.png", "Recognition · confidence · shared success", "The Six of Wands marks visible progress, acknowledgement, or confidence earned through effort. Let yourself receive recognition without making your worth dependent on applause. Success is strongest when it also honours the people and steady work that helped bring it about.", "Reversed, the Six of Wands may reflect recognition that has not arrived, confidence shaken by comparison, or a desire for approval that is overshadowing the work itself. A quiet achievement still counts. Reconnect with the purpose behind your effort and distinguish useful feedback from the need to please everyone.", "What achievement would still matter to you even if nobody applauded?"),
            ("Seven", "7 of wands.png", "Conviction · boundaries · holding your ground", "The Seven of Wands asks you to protect a position, boundary, or hard-won progress when it is being challenged. Stand up for what matters, but check whether every challenge deserves the same response. Conviction is most effective when paired with perspective and a clear sense of what you are defending.", "Reversed, the Seven of Wands may suggest feeling outnumbered, worn down by constant defence, or defending a position that needs reconsideration. You do not have to meet every demand alone. Decide which boundary is essential, where support is available, and whether a different strategy would protect your energy better.", "What is worth defending, and where could you ask for support instead of carrying it alone?"),
            ("Eight", "8 of wands.png", "Momentum · messages · rapid movement", "The Eight of Wands is swift movement: news, ideas, or plans arriving in quick succession. Momentum can make progress feel exciting, but it also asks for clear communication and priorities. Respond promptly where needed while leaving enough space to check details before agreeing to more than you can manage.", "Reversed, the Eight of Wands may signal delays, crossed messages, or too many things moving at once. Frustration can increase when every interruption feels urgent. Confirm what is actually time-sensitive, clarify misunderstandings, and allow a stalled plan to be reviewed before forcing it forward.", "What needs a clear response now, and what can wait until you have the full picture?"),
            ("Nine", "9 of wands.png", "Resilience · caution · near completion", "The Nine of Wands reflects resilience after repeated effort. You may be close to a goal yet understandably cautious about another setback. Protect your energy and learn from what has already happened; perseverance does not require ignoring limits or refusing help.", "Reversed, the Nine of Wands may show exhaustion, defensiveness, or difficulty trusting after a demanding stretch. You may need recovery more than another test of endurance. Check whether a boundary is protecting you or keeping all support out, and define the smallest next step that does not deepen burnout.", "What have you already survived, and what kind of rest or support would help you continue wisely?"),
            ("Ten", "10 of wands.png", "Responsibility · overload · carrying a lot", "The Ten of Wands depicts a heavy load: many responsibilities may be close to completion, but their combined weight is real. Success can become unsustainable when every task remains yours. Sort what is essential, delegate what can be shared, and make a plan for what happens after this demanding phase.", "Reversed, the Ten of Wands may indicate reaching a limit, setting a burden down, or continuing to carry responsibilities that could be renegotiated. Releasing a task is not automatically failure. Identify which obligations are truly yours, communicate your capacity, and seek practical help before pressure becomes a crisis.", "Which responsibility can be shared, postponed, or released without betraying what matters?"),
            ("Page", "Page of wands.png", "Curiosity · discovery · an emerging idea", "The Page of Wands brings the enthusiasm of discovery: a message, invitation, or idea that awakens curiosity. It is an excellent moment to explore, learn, and try something unfamiliar. Keep the energy alive by giving it a simple next step rather than demanding that it already be a complete life plan.", "Reversed, the Page of Wands may describe enthusiasm that is difficult to sustain, an idea that has not been tested, or hesitation about being seen as a beginner. Let curiosity be enough to begin. Make a small commitment, finish one part, and notice whether the interest grows through practice.", "What are you curious enough to explore before you decide where it will lead?"),
            ("Knight", "Knight of wands.png", "Bold action · adventure · strong momentum", "The Knight of Wands moves with boldness, initiative, and appetite for adventure. A decisive push can help when a situation has been stagnant. The challenge is to carry enthusiasm through the less glamorous details: check commitments, consider who else is affected, and make sure speed serves the destination.", "Reversed, the Knight of Wands may suggest impulsive action, unreliable follow-through, or energy that burns hot and disappears. Restlessness can be a signal that something needs to change, but not every urge requires an immediate leap. Choose one priority and give it enough steady attention to see what it becomes.", "Where would bold action help, and what commitment will keep it grounded?"),
            ("Queen", "Queen of wands.png", "Warm confidence · creativity · visibility", "The Queen of Wands embodies warm confidence, expressive creativity, and the ability to encourage others without shrinking yourself. Let your presence be visible and your interests take up space. This card favours generosity paired with self-respect: enthusiasm is most sustainable when your boundaries are as clear as your encouragement.", "Reversed, the Queen of Wands may point to self-doubt hidden behind performance, jealousy, or giving encouragement while neglecting your own energy. You may be comparing your path with someone else's. Return to the work and relationships that genuinely enliven you, and let confidence be built through honest action rather than constant validation.", "Where could you let yourself be more visible without performing for approval?"),
            ("King", "King of wands.png", "Vision · leadership · inspired direction", "The King of Wands turns vision into leadership and sustained direction. He represents the capacity to inspire movement while keeping sight of the larger purpose. Take initiative, communicate the aim clearly, and make room for others to contribute; good leadership creates momentum without demanding that every idea belong to you.", "Reversed, the King of Wands may reflect overconfidence, impatience with other people's pace, or a compelling vision without enough practical follow-through. Leadership can become control when it is not accountable. Revisit the evidence behind the plan, invite honest feedback, and align your influence with shared responsibility.", "How can you lead toward a vision while staying open to feedback and shared ownership?"),
        ],
    },
    "Cups": {
        "cards": [
            ("Ace", "Ace of Cup.png", "Emotional opening · compassion · connection", "The Ace of Cups offers an emotional opening: affection, creativity, compassion, or a renewed capacity to feel. It can mark the beginning of a connection or a gentler relationship with yourself. Let the feeling be welcomed without assuming it must immediately become a promise; emotional beginnings also need time and mutual care.", "Reversed, the Ace of Cups may indicate feelings held back, emotional depletion, or a beginning that needs more room before it can flow. It can be difficult to receive care when you are accustomed to giving it. Attend to your own needs, create a safe outlet for emotion, and avoid forcing intimacy before trust is ready.", "What feeling is asking to be acknowledged or cared for without being rushed?"),
            ("Two", "Tow of Cups.png", "Mutuality · partnership · honest exchange", "The Two of Cups centres mutual recognition: two people, ideas, or parts of yourself meeting with respect. Attraction or agreement matters most when it is reciprocal and honestly communicated. This card supports repair and collaboration where both sides can speak, listen, and make choices freely.", "Reversed, the Two of Cups can reflect misunderstanding, uneven effort, or a connection that needs an honest conversation. Conflict does not erase care, but affection alone cannot substitute for respect and reciprocity. Clarify what each person needs and whether both are willing to participate in repairing the imbalance.", "Where is there genuine mutuality, and where does the exchange need clearer communication?"),
            ("Three", "3 of Cup.png", "Friendship · celebration · community", "The Three of Cups celebrates friendship, shared joy, and the emotional nourishment of community. People who understand your experience can help you mark a milestone or feel less alone. Make room for celebration, while noticing which relationships feel supportive rather than simply busy or socially expected.", "Reversed, the Three of Cups may point to social exhaustion, feeling left out, or group dynamics that do not feel trustworthy. It can also suggest celebrations postponed by competing demands. Seek the kind of connection that leaves you feeling included and respected, even if that means a smaller gathering or a firmer boundary.", "Which people help you feel genuinely welcomed, and how might you make time for them?"),
            ("Four", "4 of cups.png", "Contemplation · dissatisfaction · reconsideration", "The Four of Cups brings a pause in which dissatisfaction or emotional fatigue deserves attention. An opportunity may be present, but you may not be ready to receive it—or it may not be right for you. Rather than forcing gratitude or chasing novelty, ask what is missing and what would make engagement feel meaningful again.", "Reversed, the Four of Cups may mark renewed interest after withdrawal, or restlessness that makes every option seem inadequate. You could be ready to notice an offer you previously overlooked. Take a small step back into participation, while checking whether the opportunity actually fits your needs.", "What might you be feeling that you have not yet allowed yourself to name?"),
            ("Five", "4 of cups (2).png", "Grief · disappointment · what remains", "The Five of Cups honours grief and disappointment without pretending they are small. Attention naturally goes to what was lost, yet the card also asks whether any support or possibility remains available. Turning toward what survives does not erase what mattered; it allows sorrow and continued life to occupy the same moment.", "Reversed, the Five of Cups can suggest the gradual easing of grief, readiness to accept support, or difficulty releasing regret. Healing is rarely linear and need not follow anyone else's schedule. Notice what you have learned, what can still be repaired, and what no longer needs to be punished in yourself.", "What loss needs to be acknowledged, and what support or possibility is still within reach?"),
            ("Six", "5 of cups.png", "Memory · tenderness · reconnection", "The Six of Cups returns to memory, tenderness, and the influence of earlier experiences. A reunion, familiar pleasure, or childhood perspective may bring comfort. Nostalgia can be nourishing when it connects you with what you value; let the past inform the present without requiring you to live inside it.", "Reversed, the Six of Cups may indicate being stuck in an idealized past, or becoming ready to loosen its hold and grow beyond an old role. Memories can explain a reaction without deciding your future. Ask which parts of the past you want to carry forward and which expectations belong to another time.", "Which memory comforts you, and which old expectation might you now choose differently?"),
            ("Seven", "21.png", "Imagination · many options · discernment", "The Seven of Cups presents a field of possibilities, fantasies, and choices. Imagination can reveal what you desire, but too many attractive options can blur the difference between hope and a workable plan. Name what matters most, check the practical details, and choose one possibility to explore in reality.", "Reversed, the Seven of Cups may signal confusion beginning to clear, or a choice being made without enough reflection. Escapism can feel soothing while delaying a necessary decision. Reduce the options, seek reliable information, and distinguish an appealing image from the commitments it would actually require.", "Which possibility still matters after you check what it would ask of you in practice?"),
            ("Eight", "8 of cups.png", "Departure · searching · emotional honesty", "The Eight of Cups shows a decision to leave what no longer feels emotionally sufficient, even when it once mattered. The next destination may not be clear. This card honours the honesty required to seek something more aligned, while encouraging you to distinguish thoughtful departure from a momentary wish to escape discomfort.", "Reversed, the Eight of Cups may reveal fear of leaving, a return to a situation you thought was finished, or uncertainty about whether it is time to move on. Neither staying nor leaving is automatically the brave choice. Ask what has been tried, what remains possible, and what your reasons look like when fear is set aside.", "What are you seeking that the current situation no longer provides, and have you given it a fair chance to change?"),
            ("Nine", "9 of cups.png", "Contentment · pleasure · a wish fulfilled", "The Nine of Cups celebrates satisfaction, pleasure, and a wish that may be taking shape. Enjoying what you have does not require pretending life is perfect. Check that the achievement feels nourishing in private, not only impressive from the outside, and make space to appreciate the people and choices that helped you get here.", "Reversed, the Nine of Cups may point to satisfaction that does not last, overindulgence, or a goal chosen because it looks like happiness from the outside. It can also show that a genuine wish needs a more honest definition. Ask what would make your life feel fulfilling in ordinary daily moments.", "Which desire is truly yours, and what kind of everyday life would fulfill it?"),
            ("Ten", "10 of cups.png", "Belonging · emotional fulfilment · shared joy", "The Ten of Cups imagines emotional fulfilment as something shared: belonging, care, and relationships in which people can be themselves. It may mark a moment of harmony or the values you hope to build toward. Let the image inspire connection without demanding that real family or community look perfect.", "Reversed, the Ten of Cups may reveal tension beneath an idealized picture of harmony, distance within a family, or expectations that leave little room for difference. Meaningful belonging can include difficult conversations. Focus on the specific relationships where respect and care can be practiced rather than forcing a picture-perfect outcome.", "What does belonging look like when it makes room for real people, not a perfect picture?"),
            ("Page", "Page of Cups.png", "Sensitivity · imagination · a tender message", "The Page of Cups brings emotional curiosity, imaginative attention, and the possibility of a gentle message or new feeling. Stay receptive to what moves you, even if it is not fully formed. Sensitivity can be a creative strength when paired with boundaries that help you separate intuition, hope, and what has actually been communicated.", "Reversed, the Page of Cups may indicate emotional hesitancy, daydreaming in place of communication, or feelings that are difficult to express clearly. A tender hope deserves protection, but also honest grounding. Find a simple way to say what you mean, and give yourself permission to learn as you go.", "What feeling or creative idea is just beginning to find its words?"),
            ("Knight", "Knight of cup.png", "Romance · invitation · emotional pursuit", "The Knight of Cups follows an emotional invitation with charm, imagination, and a desire to connect. Romance or creative inspiration may be in motion. Let sincerity guide the gesture: beautiful words are strongest when actions, expectations, and boundaries support them over time.", "Reversed, the Knight of Cups may describe mixed signals, idealising someone, or pursuing a feeling without checking whether it is mutual and sustainable. It can also point to withdrawing when vulnerability arrives. Slow the story down enough to ask what is being offered in concrete terms and how it feels in practice.", "Do the actions in this connection match the feelings or promises being expressed?"),
            ("Queen", "Queen of Cup.png", "Empathy · emotional wisdom · receptivity", "The Queen of Cups brings empathy and emotional insight while reminding you that compassion needs boundaries. You may be able to listen deeply to another person or to your own quieter needs. Let care be receptive rather than absorbing: understanding someone's feelings does not make you responsible for managing them.", "Reversed, the Queen of Cups may reflect emotional overwhelm, blurred boundaries, or care that has become self-neglect. Intuition can be hard to hear when you are carrying everyone's feelings. Return to your own body and limits, and choose a form of compassion that does not require abandoning yourself.", "How can you offer care here while remaining attentive to your own emotional limits?"),
            ("King", "King of cup.png", "Emotional steadiness · diplomacy · compassion", "The King of Cups represents emotional steadiness: the ability to feel deeply while responding with perspective. Compassionate leadership, thoughtful listening, or calm communication may be needed. Emotional control is not suppression; it is giving feelings enough space to inform your choices without letting one wave decide everything.", "Reversed, the King of Cups may signal feelings contained until they spill over, emotional distance, or influence used to steer others indirectly. Ask whether a calm exterior is hiding a need for support or a difficult truth. Communicate plainly and seek help if the emotional load is becoming hard to carry.", "What would honest emotional steadiness look like in this situation, beyond simply keeping the peace?"),
        ],
    },
    "Swords": {
        "cards": [
            ("Ace", "Ace of Sword.png", "Clarity · truth · a decisive idea", "The Ace of Swords cuts through confusion with a clear idea, conversation, or decision. New information can bring relief, but clarity also carries responsibility: check the facts and communicate without using truth as a weapon. A precise question may open more progress than a forceful conclusion.", "Reversed, the Ace of Swords can point to confusion, an untested assumption, or communication that has become distorted. A sharp opinion is not always a clear one. Pause before acting, separate evidence from interpretation, and make room to correct a story when new information appears.", "What needs to be said plainly, and what facts should you verify before deciding?"),
            ("Two", "Two of Sword.png", "Indecision · competing truths · a pause", "The Two of Swords reflects a decision held in balance while competing needs are considered. A temporary pause can protect you from reacting too quickly, but avoiding information cannot make a choice disappear. Gather what is missing, listen to each concern, and define when you will revisit the decision.", "Reversed, the Two of Swords may describe indecision becoming stressful, information being avoided, or a stalemate beginning to shift. You may not be able to satisfy every preference. Clarify the consequences of each option and choose the one most consistent with your values and actual capacity.", "What information or honest conversation would help you move from stalemate to a considered choice?"),
            ("Three", "3 of swords.png", "Heartache · truth · processing loss", "The Three of Swords acknowledges pain caused by disappointment, separation, or a truth that hurts to face. Naming the hurt can be part of healing; it does not require defining your future by it. Allow grief its space and seek support from people who can listen without rushing you toward a lesson.", "Reversed, the Three of Swords may mark the beginning of emotional repair, old pain resurfacing, or a wish to move on before the hurt has been heard. Healing can be uneven. Give yourself room to process, make a needed boundary, and consider support rather than carrying the experience alone.", "What hurt deserves to be acknowledged before you ask yourself to move forward?"),
            ("Four", "4 of swords.png", "Rest · recovery · mental space", "The Four of Swords calls for recovery and deliberate mental quiet. After sustained thought or conflict, rest is part of the work, not a reward you must earn by exhaustion. Step back where possible, protect a little breathing room, and return to the issue when your perspective is less depleted.", "Reversed, the Four of Swords may suggest rest interrupted by worry, recovery postponed too long, or isolation mistaken for restoration. If you cannot take a full break, choose a smaller form of respite and ask what practical pressure can be reduced. Your mind may need a different rhythm, not more self-criticism.", "What kind of rest would actually restore you rather than merely keep you away from the problem?"),
            ("Five", "5 of swords.png", "Conflict · cost · choosing your battles", "The Five of Swords examines conflict and its cost. A win can still damage trust if it depends on humiliation, unclear rules, or refusing to listen. Protect yourself when necessary, but decide whether the goal is resolution, distance, or simply proving a point; those aims call for different responses.", "Reversed, the Five of Swords may show regret after conflict, a possibility of repair, or a harmful dynamic that remains unresolved. Apology is meaningful when paired with changed behaviour and safety. Decide what responsibility is yours, what cannot be repaired alone, and which boundary prevents the same harm repeating.", "What would resolution mean here, and is everyone willing to take responsibility for their part?"),
            ("Six", "6 of swords.png", "Transition · distance · gradual recovery", "The Six of Swords depicts movement away from a difficult mental or emotional climate toward calmer ground. The transition may be practical, relational, or internal, and it may carry memories with it. You do not have to feel completely healed before taking a step that makes life safer or more manageable.", "Reversed, the Six of Swords may reflect difficulty leaving a painful situation, delays in transition, or old concerns following you into a new setting. Sometimes the next step needs more preparation or support. Identify what can travel with you as a lesson and what needs a boundary so it does not dictate the future.", "What would make the next stage feel safer, even if you are not fully ready to leave the past behind?"),
            ("Seven", "7 of sword.png", "Strategy · discretion · honest motives", "The Seven of Swords concerns strategy, discretion, and choices made outside the full view of others. Privacy can be necessary, but secrecy can also create risk when agreements or trust are involved. Ask what you are trying to protect, whether your approach is fair, and whether a more direct route is possible.", "Reversed, the Seven of Swords may point to a hidden issue coming to light, a plan needing revision, or guilt about avoiding a direct conversation. It can also mean choosing to act with greater honesty after a period of evasion. Take responsibility without dramatizing it and make the next step transparent where appropriate.", "What are you protecting through silence, and would a more direct approach be safer or fairer?"),
            ("Eight", "8 of swords.png", "Restriction · perspective · perceived limits", "The Eight of Swords depicts feeling constrained by fear, assumptions, or circumstances that make options hard to see. The limits may be partly real, so do not blame yourself for being stuck. Identify the specific barrier, separate it from predictions about what will happen, and look for one source of support or choice.", "Reversed, the Eight of Swords may mark a growing awareness of options, or fear that continues to restrict action after circumstances have shifted. Freedom does not require a dramatic leap. Test one manageable choice, seek practical help, and notice whether the boundary is external, internal, or a combination.", "Which limit is concrete, which is an assumption, and what small test could help you tell the difference?"),
            ("Nine", "9 of swords.png", "Worry · sleeplessness · compassionate perspective", "The Nine of Swords gives form to worry, guilt, or thoughts that become louder in solitude. It recognises distress without claiming that every feared outcome is true. Bring the concern into daylight: write it down, check the evidence, and speak with someone safe. If anxiety is affecting daily life, support is available.", "Reversed, the Nine of Swords may show anxiety easing, or distress being kept hidden until it feels heavier. You do not have to solve every thought by thinking harder. Attend to sleep and support, separate a solvable problem from a recurring fear, and consider professional care if the burden persists.", "What is a fear asking for care or evidence, rather than another night of carrying it alone?"),
            ("Ten", "10 of swords.png", "An ending · exhaustion · reaching a limit", "The Ten of Swords marks a painful ending, mental exhaustion, or the recognition that a situation has reached its limit. Its drama reflects the weight of the moment, not a promise that life cannot continue. Focus on immediate care and what can be learned later; first, allow the chapter to be over.", "Reversed, the Ten of Swords may point to recovery after a difficult ending, fear of another blow, or keeping a painful chapter alive through repeated rumination. Healing can begin quietly. Protect your recovery, name what is finished, and ask what one small sign of renewed capacity would look like.", "What has reached its limit, and what would help you begin recovering without demanding instant closure?"),
            ("Page", "Page of Sword.png", "Questions · observation · new information", "The Page of Swords brings curiosity, observation, and a willingness to ask sharper questions. New information or a conversation may be developing. Keep your mind open and your sources reliable; curiosity is most useful when it does not become surveillance, gossip, or certainty based on a fragment.", "Reversed, the Page of Swords may suggest scattered research, miscommunication, or words sent before their consequences are considered. It can also reflect being watched or misunderstood. Slow down, verify information, and choose a direct conversation over an assumption built from incomplete details.", "What do you need to understand better, and which source would be reliable enough to trust?"),
            ("Knight", "40.png", "Directness · speed · determined thought", "The Knight of Swords moves quickly toward an idea, challenge, or conversation. Determination can be valuable when delay has become its own obstacle, but speed should not erase listening. Be direct about the purpose, check what you may be missing, and stay willing to change course when the facts change.", "Reversed, the Knight of Swords can describe impulsive words, a plan driven by anger, or momentum that leaves little room for consequences. A forceful argument is not always an effective one. Pause before sending or deciding, identify the outcome you want, and choose a pace that preserves understanding.", "What would improve if you slowed down enough to hear the response as well as make your point?"),
            ("Queen", "Queen of sword.png", "Discernment · boundaries · clear speech", "The Queen of Swords values discernment, honest language, and boundaries informed by experience. You can be compassionate without pretending not to see what is happening. Ask precise questions, communicate expectations clearly, and let insight sharpen your judgment without turning it into unnecessary harshness.", "Reversed, the Queen of Swords may indicate words made cutting by hurt, excessive suspicion, or a boundary hardened into distance. It can also show that a difficult truth is being withheld. Speak with clarity while checking where grief or fatigue may be shaping your interpretation.", "What truth needs clear words, and how could you express it without punishing yourself or someone else?"),
            ("King", "42.png", "Reason · strategy · accountable leadership", "The King of Swords brings strategic thought, clear standards, and decisions supported by evidence. His strength is not detachment for its own sake, but the ability to see a situation broadly and communicate the reasoning behind a choice. Use authority responsibly and leave room for human context alongside logic.", "Reversed, the King of Swords may signal rigid judgment, analysis used to avoid emotion, or authority exercised without accountability. Information can be selected to justify a conclusion already chosen. Reopen the reasoning, consider who is affected, and invite a perspective that could genuinely change your mind.", "Where does clear reasoning help, and what human perspective would make the decision more complete?"),
        ],
    },
    "Pentacles": {
        "cards": [
            ("Ace", "43.png", "Opportunity · resources · a grounded start", "The Ace of Pentacles offers a practical beginning: a resource, skill, job, health habit, or financial opportunity that could grow with care. Its promise is potential, not instant security. Check the terms, protect the foundation, and turn the opening into a manageable routine or plan.", "Reversed, the Ace of Pentacles may point to a delayed opportunity, shaky foundations, or practical details that need attention before you commit. It can also reflect undervaluing what you already have. Review the budget, time, and conditions; a slower start may be wiser than investing on hope alone.", "What practical opportunity is available, and what foundation would help it last?"),
            ("Two", "2 of pentacles.png", "Adaptability · priorities · balancing demands", "The Two of Pentacles concerns the everyday work of balancing changing demands. You may be juggling resources, time, or commitments and adjusting as circumstances shift. Flexibility helps, but constant juggling can hide a capacity problem. Review priorities and make the trade-offs explicit before every responsibility becomes urgent.", "Reversed, the Two of Pentacles may reveal overload, disorganisation, or a balance that depends on you continually compensating. You may need to simplify rather than become more efficient. Decide what can be postponed, shared, or declined, and make a realistic plan for the resources you actually have.", "What are you juggling, and which commitment needs a clearer priority or boundary?"),
            ("Three", "3 of pentacles.png", "Craft · collaboration · building skill", "The Three of Pentacles values skilled work, collaboration, and the details that turn an idea into something dependable. Progress improves when roles are clear and each contribution is respected. Ask for feedback, learn from people with different strengths, and recognise the value of careful practice.", "Reversed, the Three of Pentacles may indicate poor coordination, work that goes unrecognised, or a project where people are not aligned on standards. It can also reflect reluctance to learn from feedback. Clarify expectations and responsibilities, then decide whether collaboration can be improved or needs to change.", "What skill or conversation would help this shared work become stronger?"),
            ("Four", "4 of pentacles.png", "Security · holding on · resource boundaries", "The Four of Pentacles focuses on protecting resources and seeking security. Careful saving or a firm boundary may be appropriate, especially after uncertainty. The question is whether protection is creating stability or preventing every form of change and generosity. Define what enough security means in practical terms.", "Reversed, the Four of Pentacles may suggest loosening a grip, reconsidering a scarcity mindset, or feeling financially or emotionally exposed. Generosity should not threaten your stability, and caution need not become permanent closure. Review where you can safely share or invest and where a boundary still needs to hold.", "What are you protecting, and is that protection helping you feel secure or keeping you stuck?"),
            ("Five", "47.png", "Hardship · exclusion · seeking support", "The Five of Pentacles acknowledges material strain, insecurity, or the pain of feeling left out. It does not say that help is impossible. Identify the immediate need and the people, services, or resources that may be available; seeking support is a practical act, not a measure of your worth.", "Reversed, the Five of Pentacles may describe the first signs of recovery, openness to help, or ongoing hardship that has been hidden through shame. Improvement can be gradual and still matter. Ask specifically for what you need, check available assistance, and let others know if isolation is making the situation harder.", "What concrete support would make the next few days or weeks more manageable?"),
            ("Six", "6 of pentacles.png", "Generosity · exchange · fair support", "The Six of Pentacles explores giving and receiving resources, time, or influence. Generosity can strengthen a community when it respects the dignity and agency of everyone involved. Look at the balance of the exchange: support is most helpful when expectations are clear and help does not become control.", "Reversed, the Six of Pentacles may point to unequal exchange, support offered with strings attached, or difficulty accepting help. Money and influence can create imbalances even when intentions are kind. Clarify terms, protect your ability to choose, and consider whether giving or receiving needs a more sustainable boundary.", "Is this exchange fair, freely chosen, and sustainable for everyone involved?"),
            ("Seven", "7 of pentacles.png", "Patience · assessment · long-term growth", "The Seven of Pentacles pauses to assess what sustained effort is producing. A project may need more time, a different method, or an honest decision about whether its return justifies continued investment. Patience is active here: check the evidence, adjust the plan, and define what progress would look like.", "Reversed, the Seven of Pentacles may suggest frustration with slow results, impatience, or continued investment simply because so much has already been spent. Past effort deserves respect, but it does not obligate you to repeat an ineffective plan. Review the costs and choose based on future value rather than sunk effort.", "What evidence would tell you whether this investment of time or energy is worth continuing?"),
            ("Eight", "8 of pentacles.png", "Practice · craftsmanship · steady improvement", "The Eight of Pentacles is the discipline of building skill through repetition and attention. Progress may come from focused practice rather than a dramatic breakthrough. Choose a standard you can maintain, notice what each attempt teaches, and let mastery develop through consistent work.", "Reversed, the Eight of Pentacles may point to perfectionism, disengagement, or effort repeated without learning. You may need a better method, clearer feedback, or a break. Check whether practice is improving the result and whether the standard is realistic; sustained work should build capacity, not only consume it.", "What would you improve by practicing consistently, and what feedback could help you improve faster?"),
            ("Nine", "9 of pentacles.png", "Independence · earned comfort · self-trust", "The Nine of Pentacles reflects independence, earned comfort, and the satisfaction of being able to appreciate what you have built. Enjoying your own company and resources can be a genuine achievement. Let security support a fuller life rather than becoming another standard you must constantly prove.", "Reversed, the Nine of Pentacles may suggest financial dependence, insecurity beneath appearances, or difficulty enjoying success without comparison. It can also ask whether independence has become isolation. Review what security means beyond status and consider where support or shared enjoyment could enrich what you have built.", "What would allow you to enjoy your progress while staying connected to the support around you?"),
            ("Ten", "10 of pentacles.png", "Legacy · shared security · lasting foundations", "The Ten of Pentacles looks at long-term security, shared resources, family patterns, and the structures passed between generations. Its focus is not wealth alone; it asks what kind of stability and belonging you are building. Consider how today's practical choices support the people and values you hope will endure.", "Reversed, the Ten of Pentacles may reveal tension around family resources, inherited expectations, or a structure that looks secure but does not feel fair. A legacy can be reconsidered. Clarify agreements, boundaries, and what success means to you rather than following a model that no longer fits.", "What kind of stability or legacy do you want to build on your own terms?"),
            ("Page", "page of Pentacles.png", "Study · practical curiosity · a first investment", "The Page of Pentacles approaches a practical opportunity as a learner. A course, skill, budget, or new responsibility may be worth exploring through steady effort. Start with the details and give curiosity a structure; small, consistent steps can turn an idea into a useful capability.", "Reversed, the Page of Pentacles may indicate procrastination, a plan that lacks practical follow-through, or anxiety about beginning as a beginner. Return to the smallest workable task and set a realistic time for it. Learning becomes more dependable when it is practiced, not merely planned.", "What practical skill or goal could you begin developing in a small, repeatable way?"),
            ("Knight", "54.png", "Reliability · routine · long-term effort", "The Knight of Pentacles brings reliability, patience, and attention to the work that sustains a goal. Slow progress can be meaningful when it is consistent and responsive to results. Keep promises realistic, build a workable routine, and remember to check whether the route still leads where you want to go.", "Reversed, the Knight of Pentacles may point to stagnation, routine without purpose, or resistance to any adjustment. It can also signal inconsistent follow-through after an overly ambitious plan. Reassess the process, remove unnecessary friction, and choose a rhythm that is dependable without becoming lifeless.", "Which steady habit would make meaningful progress more likely over the next month?"),
            ("Queen", "Queen of pentacles.png", "Practical care · resourcefulness · grounded nurture", "The Queen of Pentacles combines practical competence with warmth. She represents care expressed through everyday support—managing resources, tending health, creating a welcoming space, or helping others while remaining grounded herself. Let efficiency serve wellbeing, and remember that you are also part of the life you are caring for.", "Reversed, the Queen of Pentacles may show overwork, neglecting your own needs while tending everyone else's, or anxiety about material security. Practical care can become another impossible standard. Simplify the routine, accept help, and identify one form of nourishment that is realistic rather than idealised.", "What everyday act of care would support both you and the people who rely on you?"),
            ("King", "King of Pentales.png", "Stewardship · stability · considered provision", "The King of Pentacles represents stewardship: managing resources and responsibilities with patience and a long view. He values dependability, but good provision is more than accumulation. Build stable systems, honour commitments, and use influence to create conditions in which others can also thrive.", "Reversed, the King of Pentacles may reflect materialism, inflexible control, or security pursued at the expense of health and relationships. It can also describe unreliable management of shared resources. Review the real costs of your approach, seek transparent advice where needed, and define success beyond what can be owned.", "How can you use your resources and influence responsibly without letting security become control?"),
        ],
    },
}


def slugify(name):
    return re.sub(r"-+", "-", re.sub(r"[^a-z0-9]+", "-", name.lower())).strip("-")


def esc(value):
    return html.escape(value, quote=True)


def title_words(name):
    return name.replace("The ", "", 1) if name.startswith("The ") else name


def build_cards():
    cards = []
    for name, image, numeral, keywords, upright, reversed_meaning, question in MAJOR:
        cards.append({
            "name": name, "image": image, "category": "Major Arcana", "group": "major",
            "number": numeral, "rank": name, "suit": "", "keywords": keywords,
            "upright": upright, "reversed": reversed_meaning, "question": question,
        })

    rank_numbers = {
        "Ace": "I", "Two": "II", "Three": "III", "Four": "IV", "Five": "V",
        "Six": "VI", "Seven": "VII", "Eight": "VIII", "Nine": "IX", "Ten": "X",
        "Page": "PAGE", "Knight": "KNIGHT", "Queen": "QUEEN", "King": "KING",
    }
    for suit, details in SUITS.items():
        for rank, image, keywords, upright, reversed_meaning, question in details["cards"]:
            cards.append({
                "name": f"{rank} of {suit}", "image": image, "category": suit,
                "group": suit.lower(), "number": rank_numbers[rank], "rank": rank,
                "suit": suit, "keywords": keywords, "upright": upright,
                "reversed": reversed_meaning, "question": question,
            })

    if len(cards) != 78 or len({card["name"] for card in cards}) != 78:
        raise ValueError(f"Expected 78 unique tarot cards, got {len(cards)}.")
    for card in cards:
        if not (ROOT / "cards" / card["image"]).is_file():
            raise FileNotFoundError(f"Missing artwork for {card['name']}: {card['image']}")
        card["slug"] = slugify(card["name"])
    return cards


def generate_card_previews(cards):
    preview_dir = OUTPUT / "card-previews"
    preview_dir.mkdir(parents=True, exist_ok=True)
    for card in cards:
        source = ROOT / "cards" / card["image"]
        preview = preview_dir / f"{card['slug']}.jpg"
        with Image.open(source) as image:
            image = image.convert("RGB")
            bottom_crop = max(1, round(image.height / 100))
            image = image.crop((0, 0, image.width, image.height - bottom_crop))
            image.thumbnail((260, 366), Image.Resampling.LANCZOS)
            image.save(preview, format="JPEG", quality=48, optimize=True)


