def meaning_card(card):
    url = f"{card['slug']}.html"
    image = f"card-previews/{card['slug']}.jpg"
    alt = f"{card['name']} tarot card artwork"

    def short_meaning(text, reversed_meaning=False):
        first_sentence = text.split(". ", 1)[0].rstrip(".")
        if reversed_meaning:
            first_sentence = re.sub(
                r"^(?:Reversed,\s*|Reversed\s+|In reverse,\s*)",
                "",
                first_sentence,
                flags=re.IGNORECASE,
            )
            first_sentence = first_sentence[:1].upper() + first_sentence[1:]
        if len(first_sentence) > 105:
            first_sentence = first_sentence[:102].rsplit(" ", 1)[0].rstrip(" ,;:") + "…"
        else:
            first_sentence += "."
        return first_sentence

    upright_short = short_meaning(card["upright"])
    reversed_short = short_meaning(card["reversed"], reversed_meaning=True)
    keywords = " · ".join(card["keywords"].split(" · "))
    return f"""
<a class="meaning-card" href="{url}" data-category="{esc(card['group'])}" data-search="{esc((card['name']+' '+keywords+' '+card['upright']+' '+card['reversed']).lower())}">
  <div class="meaning-card-frame">
    <div class="meaning-card-art"><img src="{image}" alt="{esc(alt)}" loading="lazy" /></div>
    <div class="meaning-card-content">
      <div class="meaning-card-title"><h2>{esc(card['name'])}</h2></div>
      <div class="meaning-card-meanings">
        <p><span class="meaning-card-label">Upright</span><span class="meaning-card-text">{esc(upright_short)}</span></p>
        <p><span class="meaning-card-label">Reversed</span><span class="meaning-card-text">{esc(reversed_short)}</span></p>
      </div>
      <span class="meaning-card-cta">Click to explore full meaning <span aria-hidden="true">→</span></span>
    </div>
  </div>
</a>"""


def generate_index(cards):
    cards_markup = "\n".join(meaning_card(card) for card in cards)
    categories = [("major", "Major Arcana"), ("wands", "Wands"), ("cups", "Cups"), ("swords", "Swords"), ("pentacles", "Pentacles"), ("all", "All 78 cards")]
    filters = "\n".join(
        f'<button type="button" class="meaning-filter{" active" if value == "all" else ""}" data-filter="{value}" aria-pressed="{str(value == "all").lower()}">{label}</button>'
        for value, label in categories
    )
